def build(final=None):
    G = {}; allp = []
    for k, (desc, boards, pieces, parts, plays) in GAMES.items():
        b = 'bg_%s' % k
        G[b + '_desc'] = [desc]; G[b + '_board'] = boards; G[b + '_pieces'] = pieces; G[b + '_parts'] = parts; G[b + '_play'] = plays
        G[b + '_board_prompt'] = ['The board for %s, laid flat on __bg_table__ and photographed from above. It is __%s_board__, __bg_decade_look__. It is __bg_condition__. __bg_photo__' % ('__%s_desc__' % b, b)]
        G[b + '_play_prompt'] = ['A tabletop scene of __%s_desc__, in progress on __bg_table__. On __%s_board__ are __%s_pieces__, with %s. Next to the board you can see __%s_parts__. Everything is __bg_decade_look__. __bg_photo__' % (b, b, b, '__%s_play__' % b, b)]
        G[b + '_pieces_prompt'] = ['Close-up of the pieces for __%s_desc__, __%s_pieces__, gathered on __bg_table__. Close-up photograph in sharp focus.' % (b, b)]
        G[b + '_box_prompt'] = ['The box for __%s_desc__, a cardboard box with a lift-off lid printed with the title "__bg_title2__" in big letters above a picture of the game, __bg_decade_look__. The box is __bg_box_condition__. __bg_photo__' % b,
                                'The open box for __%s_desc__, the lid printed "__bg_title2__" leaning beside it and the inside tray holding __%s_pieces__ and __%s_parts__. __bg_photo__' % (b, b, b)]
        G[b + '_contents_prompt'] = ['Everything from __%s_desc__ laid out neatly on __bg_table__ and photographed from above, with __%s_board__, __%s_pieces__ and __%s_parts__, beside the box lid printed "__bg_title2__". __bg_photo__' % (b, b, b, b)]
        G[b + '_prompt'] = ['__%s_%s_prompt__' % (b, x) for x in ('board', 'play', 'play', 'pieces', 'box', 'contents')]
        allp.append('__%s_prompt__' % b)
    G['bg_title2'] = ['__name_hero_adj__ __name_hero_noun__', 'The Great __name_word__ Game', '__name_town__ Classic', 'Family __name_word__', '__name_word__ Master', 'Grand __name_hero_noun__']
    G['bg_classic_any_prompt'] = allp
    G['bg_all_any_prompt'] = allp + ['__bg_any_prompt__'] * 2
    return G

